// Small, escaped text renderer: tables, inline code and fenced code only.
function learningCells(line){let s=line.trim();if(s.startsWith('|'))s=s.slice(1);if(s.endsWith('|')&&!s.endsWith('\\|'))s=s.slice(0,-1);return s.split(/(?<!\\)\|/).map(c=>c.trim().replace(/\\\|/g,'|'))}
function learningInline(text){return String(text).split(/(`[^`]+`)/g).map(t=>t.startsWith('`')&&t.endsWith('`')?'<code>'+esc(t.slice(1,-1))+'</code>':esc(t)).join('')}
function learningDivider(line){const cells=learningCells(line);return cells.length>1&&cells.every(c=>/^:?-{3,}:?$/.test(c))}
function renderLearningText(text){const lines=String(text??'').replace(/\r\n?/g,'\n').split('\n');let out=[],paragraph=[];const flush=()=>{if(paragraph.length){out.push('<p>'+paragraph.map(learningInline).join('\n')+'</p>');paragraph=[]}};for(let i=0;i<lines.length;i++){if(lines[i].trim().startsWith('```')){flush();let code=[];while(++i<lines.length&&!lines[i].trim().startsWith('```'))code.push(lines[i]);out.push('<pre><code>'+esc(code.join('\n'))+'</code></pre>')}else if(i+1<lines.length&&lines[i].includes('|')&&learningDivider(lines[i+1])){flush();const headers=learningCells(lines[i]);i++;let rows=[];while(i+1<lines.length&&lines[i+1].includes('|')&&lines[i+1].trim()){rows.push(learningCells(lines[++i]))}out.push('<div class="learning-table-wrap" role="region" aria-label="Learning reference table" tabindex="0"><table><thead><tr>'+headers.map(c=>'<th scope="col">'+learningInline(c)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(row=>'<tr>'+headers.map((_,n)=>'<td>'+learningInline(row[n]||'')+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>')}else if(!lines[i].trim()){flush()}else paragraph.push(lines[i])}flush();return '<div class="learning-text">'+out.join('')+'</div>'}
function learningRowsMarkdown(rows){const cleaned=rows.filter(r=>r.some(c=>c.trim()));if(!cleaned.length)return '';const cols=Math.max(...cleaned.map(r=>r.length));const line=r=>'| '+Array.from({length:cols},(_,i)=>(r[i]||'').replace(/\r?\n/g,' ').replace(/\|/g,'\\|').trim()).join(' | ')+' |';return [line(cleaned[0]),line(Array(cols).fill('---')),...cleaned.slice(1).map(line)].join('\n')}
function learningClipboardTable(clipboard){const html=clipboard.getData('text/html');if(html){const doc=new DOMParser().parseFromString(html,'text/html');const table=doc.querySelector('table');if(table){const rows=Array.from(table.rows,r=>Array.from(r.cells,c=>c.textContent||''));return learningRowsMarkdown(rows)}}const plain=clipboard.getData('text/plain');if(plain.includes('\t')&&plain.includes('\n'))return learningRowsMarkdown(plain.trim().split(/\r?\n/).map(r=>r.split('\t')));return null}
function resetLearningPreview(id){const preview=document.getElementById(id+'Preview'),button=document.querySelector('[data-learning-preview="'+id+'"]');if(preview)preview.classList.add('hidden');if(button){button.textContent='Preview';button.setAttribute('aria-expanded','false')}}
function insertLearningText(area,text){const start=area.selectionStart,end=area.selectionEnd;const before=start>0?'\n\n':'',after=end<area.value.length?'\n\n':'';const value=before+text+after;if(area.maxLength>0&&area.value.length-(end-start)+value.length>area.maxLength){toast('This table is too long for the entry. Try a smaller section.');return}area.setRangeText(value,start,end,'end');area.dispatchEvent(new Event('input',{bubbles:true}));area.focus()}
function setupLearningText(){for(const id of ['journalEntryText','body']){const area=document.getElementById(id);const toolbar=document.createElement('div');toolbar.className='learning-toolbar';toolbar.innerHTML='<button type="button" data-learning-table="'+id+'">＋ Table</button><button type="button" data-learning-preview="'+id+'" aria-controls="'+id+'Preview" aria-expanded="false">Preview</button>';area.before(toolbar);const hint=document.createElement('p');hint.className='learning-hint';hint.textContent='Paste a table from ChatGPT, Docs or a spreadsheet. You can also use a Markdown table or ``` code block.';const preview=document.createElement('div');preview.id=id+'Preview';preview.className='learning-preview hidden';area.after(hint,preview);area.addEventListener('paste',event=>{if(!event.clipboardData)return;const table=learningClipboardTable(event.clipboardData);if(table){event.preventDefault();insertLearningText(area,table)}});area.addEventListener('input',()=>{if(!preview.classList.contains('hidden'))preview.innerHTML=renderLearningText(area.value)||'Your preview will appear here.'})}document.addEventListener('click',e=>{const button=e.target.closest('button');if(!button)return;if(button.dataset.learningTable){insertLearningText(document.getElementById(button.dataset.learningTable),'| Syntax | Meaning | Example |\n| --- | --- | --- |\n| `print()` | Displays a value | `print(100)` |\n|  |  |  |')}if(button.dataset.learningPreview){const id=button.dataset.learningPreview,preview=document.getElementById(id+'Preview');const show=preview.classList.contains('hidden');preview.classList.toggle('hidden',!show);if(show)preview.innerHTML=renderLearningText(document.getElementById(id).value);button.textContent=show?'Hide preview':'Preview';button.setAttribute('aria-expanded',String(show))}})}
setupLearningText();
